selector_to_html = {"a[href=\"#define-and-place-a-path\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Define and place a path<a class=\"headerlink\" href=\"#define-and-place-a-path\" title=\"Link to this heading\">\u00b6</a></h2><p>A placement maps the first template station to <code class=\"docutils literal notranslate\"><span class=\"pre\">start_position</span></code>, rotates the\ncenterline, then establishes the cross-section roll. The initial floor vector\nis expressed in assembly coordinates and points from the passage centroid\ntoward its floor. It is projected perpendicular to the initial tangent. A\nparallel or zero vector raises. The remaining frames use minimal-rotation\ntransport. No central reference line is needed.</p><p>The path passes through each passage\u2019s <strong>area centroid</strong>, including when its\nsection varies. Section dimensions are independent of placement. The user\ncontrols whether adjacent copies meet without gaps or overlaps.</p>", "a[href=\"pipes.html#route-a-pipe-along-a-curve\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Route a pipe along a curve<a class=\"headerlink\" href=\"#route-a-pipe-along-a-curve\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">Path.from_curve()</span></code> makes a path from a curve: a spline, a helix, or any shape\nyou can write as a function. Here a SciPy <code class=\"docutils literal notranslate\"><span class=\"pre\">CubicSpline</span></code> routes a pipe between\ntwo flanges, one at the origin facing up and one at <span class=\"math notranslate nohighlight\">\\((0.5, 0.4, 0.6)\\)</span> facing\nalong <span class=\"math notranslate nohighlight\">\\(+x\\)</span>, through one waypoint between them. Its end conditions fix the\ndirection at each end, so the pipe leaves and enters both flanges square to\nthem:</p>", "a[href=\"../autoapi/pyskyfire/thermo/fluid/Fluid.html#pyskyfire.thermo.fluid.Fluid\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.fluid.Fluid\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.fluid.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Fluid</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">type</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">propellants</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fractions</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">basis</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'mass'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">precision</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">3</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Mixture helper for fluids.</p><p>Stores a set of component names and composition.</p><p class=\"rubric\">Notes</p><p>Fractions are re-normalized internally when converting to mole basis to\nguard against small rounding errors.</p></dd>", "a[href=\"../autoapi/pyskyfire/heat_exchanger/index.html#module-pyskyfire.heat_exchanger\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.heat_exchanger<a class=\"headerlink\" href=\"#module-pyskyfire.heat_exchanger\" title=\"Link to this heading\">\u00b6</a></h1><p>Path-based heat exchangers with prescribed gas or coupled fluid circuits.</p>", "a[href=\"../autoapi/pyskyfire/common/solids/index.html#pyskyfire.common.solids.copper\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.solids.copper\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.solids.</span></span><span class=\"sig-name descname\"><span class=\"pre\">copper</span></span></dt><dd></dd>", "a[href=\"#build-a-path-based-heat-exchanger\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Build a path-based heat exchanger<a class=\"headerlink\" href=\"#build-a-path-based-heat-exchanger\" title=\"Link to this heading\">\u00b6</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">pyskyfire.heat_exchanger</span></code> supports both prescribed surrounding gas and two\nfluids coupled through a wall. Channels use the same <code class=\"docutils literal notranslate\"><span class=\"pre\">ducts.Path</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">PathNode</span></code>,\nand <code class=\"docutils literal notranslate\"><span class=\"pre\">PathStation</span></code> objects as pipes, and the existing rounded/squared sections.\nAll geometry angles are radians. Lengths are metres.</p>", "a[href=\"#connect-two-fluids\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Connect two fluids<a class=\"headerlink\" href=\"#connect-two-fluids\" title=\"Link to this heading\">\u00b6</a></h2><p>Both circuits have their own inlet, fluid, path, section and flow rate. A\n<code class=\"docutils literal notranslate\"><span class=\"pre\">ThermalLink</span></code> joins selected <strong>segments</strong>, indexed by their upstream station:</p>", "a[href=\"../autoapi/pyskyfire/ducts/path/index.html#pyskyfire.ducts.path.rotation_about_axis\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.rotation_about_axis\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">rotation_about_axis</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">axis</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return a proper 3x3 rotation; <code class=\"docutils literal notranslate\"><span class=\"pre\">angle</span></code> is in radians.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/components/ThrustChamberComponent.html#pyskyfire.viz.components.ThrustChamberComponent\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.components.ThrustChamberComponent\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.components.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ThrustChamberComponent</span></span></dt><dd><p>Cooling-channel surfaces with optional RegenResult fields.</p><p>Each layout seed is constructed once. Instances share its immutable mesh\nand fields and carry separate rotations and identities. No hot wall is\nconstructed. <code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_N.inlet/outlet</span></code> anchors refer to the first seed\u2019s\nfirst channel, at its end-section polygon centre, not a manifold port.\nEvery channel also exposes its own inlet/outlet anchors.</p><p>A circuit with a result records its coolant\u2019s CoolProp name as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">metadata[\"fluid\"]</span></code>. <code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_colors</span></code> paints each circuit apart;\nwithout it every channel takes the default colour.</p></dd>", "a[href=\"#pressure-and-heat-transfer-models\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Pressure and heat-transfer models<a class=\"headerlink\" href=\"#pressure-and-heat-transfer-models\" title=\"Link to this heading\">\u00b6</a></h2><p>Shared scalar functions now live in <code class=\"docutils literal notranslate\"><span class=\"pre\">common.physics</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">common.friction</span></code>, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">common.momentum</span></code>. Pressure includes Darcy friction, the existing distributed\ncurvature correction, and reversible acceleration. The energy march conserves\n<code class=\"docutils literal notranslate\"><span class=\"pre\">h</span> <span class=\"pre\">+</span> <span class=\"pre\">velocity**2/2</span></code>, using static pressure for fluid-property queries.</p><p>Internal turbulent convection uses\n<a class=\"reference external\" href=\"https://ht.readthedocs.io/en/release/ht.conv_internal.html#ht.conv_internal.turbulent_Gnielinski\">Gnielinski</a>.\nThe straight Darcy factor is shared with the friction calculation; the coil\nfriction multiplier is not automatically treated as a heat-transfer multiplier.\nGnielinski\u2019s range is enforced. Properties are bulk values, corrected for a\nheated fluid by Gnielinski\u2019s gas factor <code class=\"docutils literal notranslate\"><span class=\"pre\">(T_b/T_w)^0.45</span></code>, where <code class=\"docutils literal notranslate\"><span class=\"pre\">T_w</span></code> is the\nwall temperature at the fluid interface. It was fitted at moderate temperature\nratios; a cryogen against a hot wall is an extrapolation. A cooled fluid is not\ncorrected. Pass <code class=\"docutils literal notranslate\"><span class=\"pre\">property_correction=False</span></code> to a circuit for bulk properties.</p>", "a[href=\"../autoapi/pyskyfire/ducts/path/Path.html#pyskyfire.ducts.path.Path.from_nodes\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.Path.from_nodes\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_nodes</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nodes</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/ducts/path/PathNode.html#pyskyfire.ducts.path.PathNode\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.PathNode\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PathNode</span></span></dt><dd><p>Human-friendly route vertex consumed by <code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">generate_path_stations()</span></code>.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene.add\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene.add\">\n<span class=\"sig-name descname\"><span class=\"pre\">add</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">component</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transform</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">position</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">parent</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">anchor</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">attach_to</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tags</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">()</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/heat_exchanger/circuit/PrescribedGas.html#pyskyfire.heat_exchanger.circuit.PrescribedGas\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.heat_exchanger.circuit.PrescribedGas\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.heat_exchanger.circuit.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PrescribedGas</span></span></dt><dd><p>Fixed surrounding flow: callbacks receive assembly position and wall T.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">temperature</span></code> may be a constant or <code class=\"docutils literal notranslate\"><span class=\"pre\">temperature(position)</span></code>; coefficient\nmay be a constant or <code class=\"docutils literal notranslate\"><span class=\"pre\">coefficient(position,</span> <span class=\"pre\">wall_temperature)</span></code> [W/m\u00b2/K].</p></dd>", "a[href=\"../autoapi/pyskyfire/heat_exchanger/circuit/ThermalLink.html#pyskyfire.heat_exchanger.circuit.ThermalLink\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.heat_exchanger.circuit.ThermalLink\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.heat_exchanger.circuit.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ThermalLink</span></span></dt><dd><p>Pair finite volumes on two paths through ONE shared wall.</p><p>Each (i,j) pair couples the segment beginning at station i on a to the\nsegment beginning at station j on b. Reverse j for counterflow. All copied\nchannels are paired one-to-one. Contact areas [m\u00b2 per pair per copy] may be\nexplicit, otherwise use the smaller exposed surface area. Wall thickness\nis evaluated at the midpoint s on circuit a; it is never counted twice.</p></dd>", "a[href=\"#construct-a-channel-bank\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Construct a channel bank<a class=\"headerlink\" href=\"#construct-a-channel-bank\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">mass_flow</span></code> is the <strong>total bank flow</strong>. It is split equally among placements.\nThe solver represents one channel and verifies that all its copies see the\nsame prescribed gas conditions. Use separate circuits when the thermal\nconditions differ. There is no hydraulic flow-balancing solve.</p><p>Dimensions accept constants, arrays with one entry per path station, or\nfunctions of arc length <code class=\"docutils literal notranslate\"><span class=\"pre\">s</span></code>. Use <code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">angle</span></code> instead of the two widths\nfor sector-defined sections. <code class=\"docutils literal notranslate\"><span class=\"pre\">Wall.thickness(s)</span></code> defines floor thickness;\nsquared roof and sidewall settings still apply independently. A complete\n<code class=\"docutils literal notranslate\"><span class=\"pre\">SectionProfiles</span></code> can instead be passed as <code class=\"docutils literal notranslate\"><span class=\"pre\">section_profiles=</span></code>.</p>", "a[href=\"../autoapi/pyskyfire/heat_exchanger/circuit/Inlet.html#pyskyfire.heat_exchanger.circuit.Inlet\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.heat_exchanger.circuit.Inlet\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.heat_exchanger.circuit.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Inlet</span></span></dt><dd><p>Bank inlet: temperature [K], static pressure [Pa], TOTAL mass flow [kg/s].</p></dd>", "a[href=\"../autoapi/pyskyfire/heat_exchanger/solver/HeatExchanger.html#pyskyfire.heat_exchanger.solver.HeatExchanger.solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.heat_exchanger.solver.HeatExchanger.solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlets</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">boundaries</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">friction_model</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'fluids'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">max_iterations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">250</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tolerance</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1e-07</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">relaxation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.5</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/heat_exchanger/solver/HeatExchanger.html#pyskyfire.heat_exchanger.solver.HeatExchanger\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.heat_exchanger.solver.HeatExchanger\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.heat_exchanger.solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">HeatExchanger</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">circuits</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thermal_links</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">()</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">flow_connections</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">()</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>An assembly of banks, shared walls, and optional series headers.</p><p>Boundary mappings and inlet mappings use circuit names. For series banks,\nsupply an inlet only for the first bank. Thermal links may pair arbitrary\nsegment indices; exposed-area budgets prevent overlapping thermal links.\nA prescribed boundary heats whatever exposed area is not assigned a link.</p></dd>", "a[href=\"../autoapi/pyskyfire/thermo/transport/FluidTransport.html#pyskyfire.thermo.transport.FluidTransport\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.transport.FluidTransport\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.transport.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidTransport</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../autoapi/pyskyfire/thermo/fluid/Fluid.html#pyskyfire.thermo.fluid.Fluid\" title=\"pyskyfire.thermo.fluid.Fluid\"><span class=\"pre\">Fluid</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd><p>CoolProp-backed transport/thermo properties for a single fluid.</p><p>Thin wrapper around <strong>CoolProp</strong> that exposes convenient getters using a\n<a class=\"reference internal\" href=\"../autoapi/pyskyfire/thermo/fluid/Fluid.html#pyskyfire.thermo.fluid.Fluid\" title=\"pyskyfire.thermo.fluid.Fluid\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Fluid</span></code></a> to obtain the CoolProp fluid string.</p><p class=\"rubric\">Notes</p></dd>", "a[href=\"../autoapi/pyskyfire/heat_exchanger/circuit/HeatExchangerCircuit.html#pyskyfire.heat_exchanger.circuit.HeatExchangerCircuit\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.heat_exchanger.circuit.HeatExchangerCircuit\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.heat_exchanger.circuit.</span></span><span class=\"sig-name descname\"><span class=\"pre\">HeatExchangerCircuit</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">path</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cross_section</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wall</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">dimensions</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">section_profiles</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">placements</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">heat_transfer</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">laminar_nusselt</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">3.66</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">property_correction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">True</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Identical parallel copies of one path, each receiving equal mass flow.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">dimensions</span></code> is a mapping accepted by SectionProfiles.from_dimensions;\neach value may be a scalar, station array, or function of path distance s.\nWall.thickness(s) supplies the floor thickness (and rounded tube thickness).\nCross-section roof and sidewall settings retain their own definitions.\nAlternatively supply a complete <code class=\"docutils literal notranslate\"><span class=\"pre\">section_profiles</span></code> object.</p><p>Path stations anchor the passage area centroid. The local section +u axis\npoints floor-to-roof. One thermal solution represents all identical copies;\nprescribed boundaries are checked for equality across placements.</p><p>The default internal coefficient is Gnielinski with bulk properties,\ncorrected for a heated fluid by <code class=\"docutils literal notranslate\"><span class=\"pre\">(T_b/T_w)^0.45</span></code>. <code class=\"docutils literal notranslate\"><span class=\"pre\">property_correction=False</span></code>\nleaves the bulk-property value uncorrected. Neither applies to a supplied\n<code class=\"docutils literal notranslate\"><span class=\"pre\">heat_transfer</span></code> callback.</p></dd>", "a[href=\"#put-an-exchanger-and-chamber-in-the-same-scene\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Put an exchanger and chamber in the same scene<a class=\"headerlink\" href=\"#put-an-exchanger-and-chamber-in-the-same-scene\" title=\"Link to this heading\">\u00b6</a></h2><p>Passing a <code class=\"docutils literal notranslate\"><span class=\"pre\">ChamberInstallation</span></code> uses its simulation transform automatically.\nA raw <code class=\"docutils literal notranslate\"><span class=\"pre\">HeatExchanger</span></code> instead uses assembly coordinates and supports ordinary\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Scene.add(position=...,</span> <span class=\"pre\">rotation=...)</span></code> placement. If the chamber itself has a\nscene transform, add the installed exchanger with <code class=\"docutils literal notranslate\"><span class=\"pre\">parent=chamber_node</span></code> so\nboth move together. Explicit scene placement overrides the installation\u2019s root\ntransform, and affects the drawing only.</p><p>Each channel is drawn as its wetted passage, the surface the coolant touches,\nnot the outer envelope of its walls. The adapter exposes fluid temperature,\nstatic pressure, velocity, enthalpy, and <code class=\"docutils literal notranslate\"><span class=\"pre\">T_coolant_wall</span></code>, the wall\ntemperature at the wetted interface, in the field selector. <code class=\"docutils literal notranslate\"><span class=\"pre\">T_coolant_wall</span></code>\nuses contact-area averages on each exposed surface segment; inactive surfaces\nstay uncoloured. The opposite interface is not drawn; it remains in\n<code class=\"docutils literal notranslate\"><span class=\"pre\">result.walls</span></code>. Each copied channel has inlet/outlet anchors; root\n<code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_N.inlet/outlet</span></code> anchors refer to the first copy.</p>", "a[href=\"#examples-and-reports\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Examples and reports<a class=\"headerlink\" href=\"#examples-and-reports\" title=\"Link to this heading\">\u00b6</a></h2><p>The first heats oxygen with hydrogen in counterflow. The second makes a shallow\nV-shaped ring pair and six radial spokes with paired straight return channels.\nBoth produce interactive reports under <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/heat_exchanger/output/</span></code>.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">psf.viz.heat_exchanger_report(exchanger,</span> <span class=\"pre\">result,</span> <span class=\"pre\">installation=installation)</span></code>\nincludes swept geometry, total/per-channel flow, areas, fluid temperature,\nstatic pressure, velocity, both wall-interface temperatures, and energy balance.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">result.walls</span></code> identifies each wall\u2019s surfaces and segment indices.</p>", "a[href=\"../autoapi/pyskyfire/index.html#module-pyskyfire\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire<a class=\"headerlink\" href=\"#module-pyskyfire\" title=\"Link to this heading\">\u00b6</a></h1><p>pyskyfire - A Python library for rocket engine simulation and design.</p>", "a[href=\"../autoapi/pyskyfire/regen/thrust_chamber/Wall.html#pyskyfire.regen.thrust_chamber.Wall\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.Wall\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.thrust_chamber.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Wall</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">material</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">role</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'main'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Single structural wall or coating layer in a thrust chamber.</p><p>Encapsulates material and thickness information for heat-conduction\ncalculations.</p></dd>", "a[href=\"../autoapi/pyskyfire/ducts/path/PathPlacement.html#pyskyfire.ducts.path.PathPlacement\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.path.PathPlacement\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.path.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PathPlacement</span></span></dt><dd><p>Place the first path station and establish its section roll.</p><p>The rotation maps template coordinates into assembly coordinates. The\ninitial floor direction is expressed in assembly coordinates, points from\nthe passage centroid toward its floor, and is projected perpendicular to\nthe starting tangent. Frame columns are (floor-to-roof, lateral, tangent).\nAll subsequent section orientations use minimal-rotation transport.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/heat_exchanger_component/HeatExchangerComponent.html#pyskyfire.viz.heat_exchanger_component.HeatExchangerComponent\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.heat_exchanger_component.HeatExchangerComponent\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.heat_exchanger_component.</span></span><span class=\"sig-name descname\"><span class=\"pre\">HeatExchangerComponent</span></span></dt><dd><p>Display an exchanger or chamber installation in the shared Scene.</p><p>Each channel is drawn as its wetted passage, the surface the coolant\ntouches, not the outer envelope of its walls. Raw exchangers use assembly\ncoordinates. Installations carry their simulation transform, relative to\nthe parent chamber; explicit Scene.add placement\noverrides it. Each channel has inlet/outlet anchors. Root anchors\ncircuit_N.inlet/outlet refer to the first copy; origin is the assembly datum.</p><p>Optional results provide T_static, p_static, velocity, coolant_enthalpy\nand T_coolant_wall, the wall temperature at the wetted interface. Wall\ntemperatures are area averages per exposed surface and segment. Inactive\nportions remain NaN. The opposite (gas-side) interface is not drawn.\nWith results, each circuit records its CoolProp fluid name as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">metadata[\"fluid\"]</span></code>. <code class=\"docutils literal notranslate\"><span class=\"pre\">circuit_colors</span></code> paints each circuit apart;\nwithout it every channel takes the default colour.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.scene.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Scene</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">title</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'Pyskyfire</span> <span class=\"pre\">3D'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">color_by</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">clim</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">show_axes</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Assemble components for desktop or standalone HTML display.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">anchor</span></code> names the added component\u2019s local anchor; <code class=\"docutils literal notranslate\"><span class=\"pre\">attach_to</span></code> is a\nworld-space Anchor. Attachment mates their outward x axes in opposition.\nIt is a one-time placement calculation, with no fluid-network constraints.\nExplicit placement and anchor placement are mutually exclusive.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tags</span></code> labels the added node, a string or an iterable of them. Nodes\nsharing a tag appear together as one group in the HTML viewer, so a\ngrouping written into the script survives regenerating the results.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">show_axes</span></code> adds a corner orientation triad marking the scene axes\n(x red, y green, z blue). It is an orientation cue only, not a measuring\ngrid: it carries no ticks and does not indicate the origin or scale.</p></dd>", "a[href=\"#install-in-a-thrust-chamber\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Install in a thrust chamber<a class=\"headerlink\" href=\"#install-in-a-thrust-chamber\" title=\"Link to this heading\">\u00b6</a></h2><p>Placement converts every station into chamber coordinates. The chamber\u2019s\nexisting aerothermodynamics provides recovery temperature at its axial\nposition. Gas temperature, chemistry, and flow remain prescribed.</p><p>The exterior coefficient can be a constant or\n<code class=\"docutils literal notranslate\"><span class=\"pre\">coefficient(chamber_position,</span> <span class=\"pre\">wall_temperature)</span></code>. If omitted, the adapter\nuses the existing Bartz-style reference-temperature correlation. This is an\nengineering approximation for immersed hardware; select an appropriate\ncoefficient for the actual baffle/duct arrangement. There is no resolved\nexternal blockage loss or radiation model in this first implementation.</p>", "a[href=\"../autoapi/pyskyfire/regen/cross_section/CrossSectionSquared.html#pyskyfire.regen.cross_section.CrossSectionSquared\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.CrossSectionSquared\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.cross_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CrossSectionSquared</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">sidewall_half_thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">8</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof_thickness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'arc'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'arc'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exposure</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">enable_fin</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">ChannelSection</span></code></p><p>Squared passages with independently straight or curved floor and roof.</p><p>sidewall_half_thickness [m] is ONE tube sidewall\u2019s normal thickness,\nequivalent to HALF the shared rib between adjacent chamber channels. A\nconstant or design-input callable is accepted. A former 1 mm full rib is\ntherefore specified as 0.5 mm here.</p><p>Floor thickness comes from SectionProfiles.t_wall. roof_thickness defaults\nto that thickness and may instead be a constant or callable. floor and roof\nindependently accept \u201carc\u201d or \u201cline\u201d. Direct width profiles use the\ndistance between internal sidewall endpoints. With sector profiles, the\nexisting constant-material-width rib construction determines those\nendpoints; choosing a line joins the same endpoints with a chord.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene.save_html\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene.save_html\">\n<span class=\"sig-name descname\"><span class=\"pre\">save_html</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">path</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
